import 'package:dio/dio.dart';

/// Stable tokens for errors generated by the app itself (connectivity,
/// generic load failures, diagnosis-flow validation).
///
/// Providers store these tokens instead of localized text so the UI can map
/// them through `String.localizedError(l10n)` and retranslate immediately
/// when the user switches language. Text returned by the backend is stored
/// unchanged and therefore stays as-is (the backend is Vietnamese-only).
abstract final class LocalApiError {
  static const connectivity = 'local:connectivity';
  static const loadData = 'local:loadData';
  static const noPatient = 'local:noPatient';
  static const formLoadFailed = 'local:formLoadFailed';
  static const badRequestPrefix = 'local:badRequest:';
  static const missingRequiredPrefix = 'local:missingRequired:';
  static const invalidNumberPrefix = 'local:invalidNumber:';
  static const allergyRequired = 'local:allergyRequired';
  static const allergyYesRequired = 'local:allergyYesRequired';
  static const allergyOtherRequired = 'local:allergyOtherRequired';
  static const microbialPathogenRequired = 'local:microbialPathogenRequired';
  static const noResultToSave = 'local:noResultToSave';
  static const noProtocolToSave = 'local:noProtocolToSave';
  static const selectMedicineRequired = 'local:selectMedicineRequired';

  /// Prefix of the "which fields failed BE validation" message; the rest of
  /// the token is the comma-separated field names.
  static const invalidObservationsPrefix = 'local:invalidObservations:';
}

/// Domain-specific failure surfaced from failed `Result` envelopes;
/// controllers map it into error states (guidelines Rule 3/5).
class ApiException implements Exception {
  const ApiException(
    this.statusCode,
    this.message, {
    this.details,
  });

  final int statusCode;
  final String message;

  /// Per-field validation details (`error.detail`), e.g. the id of the
  /// clinical variable that failed validation and why.
  final Map<String, String>? details;

  @override
  String toString() => 'ApiException($statusCode): $message';
}

/// True for statuses where a token refresh + retry can recover the call.
bool isAuthRetryable(int statusCode) => statusCode == 401 || statusCode == 403;

/// The backend answers with `Result` / `Result<T>`
/// (`Respira.ServiceDefaults.Contracts.Results`), serialized as:
///
/// ```json
/// { "statusCode": "SUCCESS",      "error": null,  "data": <T> }
/// { "statusCode": "FAILURE-...",  "error": { "description": "…" }, "data": null }
/// ```
///
/// `error` is non-null only on failure (Result invariant).
bool _isFailure(Map<String, dynamic> json) {
  if (json['error'] != null) return true;
  final code = json['statusCode'];
  return code is String && code.contains('FAILURE');
}

Never _throwFailure(Map<String, dynamic> json, Response<dynamic> res) {
  final error = json['error'];
  final description = error is Map ? error['description'] as String? : null;
  throw ApiException(
    res.statusCode ?? 500,
    description ?? (json['message'] as String?) ?? 'Request failed',
    details: apiErrorDetails(json),
  );
}

/// Per-field validation details of a failed `Result` envelope
/// (`error.detail`): a map of entity id → reason (e.g. clinical variable id →
/// "Tuổi should be ≥ 16"). Returns `null` when the envelope has none.
Map<String, String>? apiErrorDetails(Object? data) {
  if (data is! Map) return null;
  final error = data['error'];
  if (error is! Map) return null;
  final detail = error['detail'];
  if (detail is! Map) return null;

  final details = <String, String>{};
  for (final entry in detail.entries) {
    final value = entry.value;
    if (value == null) continue;
    details[entry.key.toString()] = value.toString();
  }
  return details.isEmpty ? null : details;
}

/// [apiErrorDetails] of a failed HTTP call (Dio throws before the envelope is
/// unwrapped, so the body has to be inspected here).
Map<String, String>? dioErrorDetails(DioException error) =>
    apiErrorDetails(error.response?.data);

/// Extracts the envelope's `data` as a typed value, throwing [ApiException]
/// on failure envelopes.
T unwrapData<T>(
  Response<dynamic> res,
  T Function(Map<String, dynamic> json) fromJson,
) {
  final json = res.data as Map<String, dynamic>;
  if (_isFailure(json)) _throwFailure(json, res);
  final data = json['data'];
  if (data == null) {
    throw ApiException(res.statusCode ?? 500, 'Empty response data');
  }
  return fromJson(data as Map<String, dynamic>);
}

/// Extracts the whole envelope's `data` field (for non-single-object
/// payloads such as lists or paginated results).
Map<String, dynamic> unwrapEnvelope(Response<dynamic> res) {
  final json = res.data as Map<String, dynamic>;
  if (_isFailure(json)) _throwFailure(json, res);
  return json['data'] as Map<String, dynamic>? ?? {};
}

/// Validates a non-generic `Result` envelope (`204`-style commands that
/// carry no payload) and throws [ApiException] on failure.
///
/// `ApplicationStatus.Updated` is returned as **204 No Content**, so Dio
/// surfaces `''`/`null` here instead of a map — only a map can be a failure
/// envelope.
void unwrapResult(Response<dynamic> res) {
  final data = res.data;
  if (data is Map<String, dynamic> && _isFailure(data)) {
    _throwFailure(data, res);
  }
}

/// Extracts the envelope's `data` scalar (for `Result<Guid>`, `Result<bool>`
/// and similar payloads that are not objects).
T unwrapScalar<T>(Response<dynamic> res, T Function(Object? data) convert) {
  final json = res.data as Map<String, dynamic>;
  if (_isFailure(json)) _throwFailure(json, res);
  final data = json['data'];
  if (data == null) {
    throw ApiException(res.statusCode ?? 500, 'Empty response data');
  }
  return convert(data);
}

/// Best-effort human message for a failed Dio call. Dio throws on non-2xx
/// before [unwrapData]/[unwrapEnvelope] run, so this inspects the error
/// response body. The backend answers failures in two shapes:
///
/// 1. The `Result` envelope — `{ statusCode, error: { description } }`
///    (handlers/`GlobalExceptionHandler`).
/// 2. ASP.NET `ValidationProblemDetails` — `application/problem+json`
///    `{ title, status, errors: { field: [messages] } }`, emitted by
///    `[ApiController]` model binding *before* the handler runs.
///
/// Only a missing response (connection/timeout) is reported as a
/// connectivity problem; everything else surfaces the server's own text.
String dioErrorMessage(DioException error) {
  final response = error.response;
  if (response == null) {
    return LocalApiError.connectivity;
  }

  final data = response.data;
  if (data is Map) {
    // 1. Result envelope.
    final err = data['error'];
    if (err is Map && err['description'] is String) {
      return err['description'] as String;
    }

    // 2. ValidationProblemDetails — prefer a field-specific message over
    // the generic `req` ("The req field is required.") one.
    final errors = data['errors'];
    if (errors is Map) {
      String? generic;
      for (final entry in errors.entries) {
        final value = entry.value;
        final message =
            value is List && value.isNotEmpty && value.first is String
            ? value.first as String
            : value is String
            ? value
            : null;
        if (message == null || message.isEmpty) continue;
        if (entry.key == 'req') {
          generic ??= message;
          continue;
        }
        return message;
      }
      if (generic != null) return generic;
    }

    // ProblemDetails / StatusCodePages fallbacks.
    for (final key in const ['description', 'message', 'detail', 'title']) {
      final value = data[key];
      if (value is String && value.isNotEmpty) return value;
    }
  }

  return '${LocalApiError.badRequestPrefix}${response.statusCode}';
}
